struct SharedMooseState {
    friends: HashMap<String, HashSet<String>>,

    #[cfg(feature = "admission-webhook")]
    client: kube::Client,
}

struct MooseTracker {
    shared: Arc<RwLock<SharedMooseState>>,
}

impl MooseTracker {
    #[cfg(feature = "admission-webhook")]
    fn new(client: &kube::Client) -> Self {
        let shared = Arc::new(RwLock::new(SharedMooseState {
            friends: HashMap::new(),
            client: client.to_owned(),
        }));
        MooseTracker { shared }
    }

    #[cfg(not(feature = "admission-webhook"))]
    fn new() -> Self {
        let shared = Arc::new(RwLock::new(SharedMooseState {
            friends: HashMap::new(),
        }));
        MooseTracker { shared }
    }
}

#[async_trait::async_trait]
impl Operator for MooseTracker {
    type Manifest = Moose;
    type Status = MooseStatus;
    type InitialState = Tagged;
    type DeletedState = Released;
    type ObjectState = MooseState;

    async fn initialize_object_state(
        &self,
        manifest: &Self::Manifest,
    ) -> anyhow::Result<Self::ObjectState> {
        let name = manifest.meta().name.clone().unwrap();
        Ok(MooseState {
            name,
            food: manifest.spec.weight / 10.0,
        })
    }

    async fn shared_state(&self) -> Arc<RwLock<SharedMooseState>> {
        Arc::clone(&self.shared)
    }

    #[cfg(feature = "admission-webhook")]
    async fn admission_hook(
        &self,
        manifest: Self::Manifest,
    ) -> krator::admission::AdmissionResult<Self::Manifest> {
        use k8s_openapi::apimachinery::pkg::apis::meta::v1::Status;
        // All moose names start with "M"
        let name = manifest.meta().name.clone().unwrap();
        info!("Processing admission hook for moose named {}", name);
        match name.chars().next() {
            Some('m') | Some('M') => krator::admission::AdmissionResult::Allow(manifest),
            _ => krator::admission::AdmissionResult::Deny(Status {
                code: Some(400),
                message: Some("Mooses may only have names starting with 'M'.".to_string()),
                status: Some("Failure".to_string()),
                ..Default::default()
            }),
        }
    }

    #[cfg(feature = "admission-webhook")]
    async fn admission_hook_tls(&self) -> anyhow::Result<krator::admission::AdmissionTls> {
        let client = self.shared.read().await.client.clone();
        let secret_name = Moose::admission_webhook_secret_name();

        let opt = Opt::from_args();
        let secret = kube::Api::<Secret>::namespaced(client, &opt.webhook_namespace)
            .get(&secret_name)
            .await?;

        Ok(admission::AdmissionTls::from(&secret)?)
    }
}

#[derive(Debug, StructOpt)]
#[structopt(
    name = "moose",
    about = "An example Operator for `Moose` custom resources."
)]
struct Opt {
    /// Send traces to Jaeger.
    /// Configure with the standard environment variables:
    /// https://github.com/open-telemetry/opentelemetry-specification/blob/main/specification/sdk-environment-variables.md#jaeger-exporter
    #[structopt(long)]
    jaeger: bool,
    /// Configure logger to emit JSON output.
    #[structopt(long)]
    json: bool,

    /// output moose crd manifest
    #[structopt(long)]
    output_crd: bool,

    #[cfg(feature = "admission-webhook")]
    /// output webhook resources manifests for the given namespace
    #[structopt(long)]
    output_webhook_resources_for_namespace: Option<String>,

    #[cfg(feature = "admission-webhook")]
    /// namespace where to install the admission webhook service and secret
    #[structopt(long, default_value = "default")]
    webhook_namespace: String,
}

fn init_logger(opt: &Opt) -> anyhow::Result<Option<opentelemetry_jaeger::Uninstall>> {
    // This isn't very DRY, but all of these combinations have different types,
    // and Boxing them doesn't seem to work.
    let guard = if opt.json {
        let subscriber = tracing_subscriber::fmt()
            .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
            .json()
            .finish();
        if opt.jaeger {
            use tracing_subscriber::layer::SubscriberExt;
            let (tracer, _uninstall) = opentelemetry_jaeger::new_pipeline()
                .from_env()
                .with_service_name("moose_operator")
                .install()?;
            let telemetry = tracing_opentelemetry::layer().with_tracer(tracer);
            let subscriber = subscriber.with(telemetry);
            tracing::subscriber::set_global_default(subscriber)?;
            Some(_uninstall)
        } else {
            tracing::subscriber::set_global_default(subscriber)?;
            None
        }
    } else {
        let subscriber = tracing_subscriber::fmt()
            .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
            .pretty()
            .finish();
        if opt.jaeger {
            use tracing_subscriber::layer::SubscriberExt;
            let (tracer, _uninstall) = opentelemetry_jaeger::new_pipeline()
                .from_env()
                .with_service_name("moose_operator")
                .install()?;
            let telemetry = tracing_opentelemetry::layer().with_tracer(tracer);
            let subscriber = subscriber.with(telemetry);
            tracing::subscriber::set_global_default(subscriber)?;
            Some(_uninstall)
        } else {
            tracing::subscriber::set_global_default(subscriber)?;
            None
        }
    };
    Ok(guard)
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> anyhow::Result<()> {
    let opt = Opt::from_args();
    let _guard = init_logger(&opt)?;

    if opt.output_crd {
        println!("{}", serde_yaml::to_string(&Moose::crd()).unwrap());
        return Ok(());
    }

    let kubeconfig = kube::Config::infer().await?;

    let tracker;

    #[cfg(feature = "admission-webhook")]
    {
        use anyhow::Context;
        use kube::api::ResourceExt;

        let client = kube::Client::try_default().await?;
        let api = kube::Api::<k8s_openapi::apiextensions_apiserver::pkg::apis::apiextensions::v1::CustomResourceDefinition>::all(client.to_owned());
        let crd = api.get(&Moose::crd().name()).await.context("moose crd needs to be installed first -- generate the necessary manifests with --output-crd")?;
        if let Some(namespace) = opt.output_webhook_resources_for_namespace {
            let resources = krator::admission::WebhookResources::from(
                Moose::admission_webhook_resources(&namespace),
            )
            .add_owner(&crd);
            println!("{}", resources);
            return Ok(());
        }
        tracker = MooseTracker::new(&client);
    }

    #[cfg(not(feature = "admission-webhook"))]
    {
        tracker = MooseTracker::new();
    }

    // Only track mooses in Glacier NP
    let params = ListParams::default().labels("nps.gov/park=glacier");

    info!("starting mooses operator");

    #[cfg(feature = "admission-webhook")]
    info!(
        r#"

If you run this example outside of Kubernetes (i.e. with `cargo run`), you need to make the webhook available.

Try the script example/assets/use-external-endpoint.sh to redirect webhook traffic to this process. If this
operator runs within Kubernetes and you use the webhook resources provided by the admission-webhook macro, 
make sure your deployment has the following labels set:

app={}

    "#,
        Moose::admission_webhook_service_app_selector()
    );

    info!(
        r#"

Running moose example. Try to install some of the manifests provided in examples/assets

    "#
    );

    // New API does not currently support Webhooks, so use legacy API if enabled.
    #[cfg(feature = "admission-webhook")]
    {
        use krator::OperatorRuntime;
        let mut runtime = OperatorRuntime::new(&kubeconfig, tracker, Some(params));
        runtime.start().await;
    }
    #[cfg(not(feature = "admission-webhook"))]
    {
        use krator::{ControllerBuilder, Manager};
        let mut manager = Manager::new(&kubeconfig);
        let controller = ControllerBuilder::new(tracker).with_params(params);
        manager.register_controller(controller);
        manager.start().await;
    }
    Ok(())
}

A failed inference request must be indicated by an HTTP error status
(typically 400). The HTTP body must contain the
*$inference_error_response* object.

    $inference_error_response =
    {
      "error": <error message string>
    }

* “error” : The descriptive message for the error.

#### Inference Request Examples

The following example shows an inference request to a model with two
inputs and one output. The HTTP Content-Length header gives the size
of the JSON object.

    POST /v2/models/mymodel/infer HTTP/1.1
    Host: localhost:8000
    Content-Type: application/json
    Content-Length: <xx>
    {
      "id" : "42",
      "inputs" : [
        {
          "name" : "input0",
          "shape" : [ 2, 2 ],
          "datatype" : "UINT32",
          "data" : [ 1, 2, 3, 4 ]
        },
        {
          "name" : "input1",
          "shape" : [ 3 ],
          "datatype" : "BOOL",
          "data" : [ true ]
        }
      ],
      "outputs" : [
        {
          "name" : "output0"
        }
      ]
    }

For the above request the inference server must return the “output0”
output tensor. Assuming the model returns a [ 3, 2 ] tensor of data
type FP32 the following response would be returned.

    HTTP/1.1 200 OK
    Content-Type: application/json
    Content-Length: <yy>
    {
      "id" : "42"
      "outputs" : [
        {
          "name" : "output0",
          "shape" : [ 3, 2 ],
          "datatype"  : "FP32",
          "data" : [ 1.0, 1.1, 2.0, 2.1, 3.0, 3.1 ]
        }
      ]
    }

### Parameters

The *$parameters* JSON describes zero or more “name”/”value” pairs,
where the “name” is the name of the parameter and the “value” is a
$string, $number, or $boolean.

    $parameters =
    {
      $parameter, ...
    }

    $parameter = $string : $string | $number | $boolean

Currently no parameters are defined. As required a future proposal may
define one or more standard parameters to allow portable functionality
across different inference servers. A server can implement
server-specific parameters to provide non-standard capabilities.

### Tensor Data

Tensor data must be presented in row-major order of the tensor
elements. Element values must be given in "linear" order without any
stride or padding between elements. Tensor elements may be presented
in their nature multi-dimensional representation, or as a flattened
one-dimensional representation.

Tensor data given explicitly is provided in a JSON array. Each element
of the array may be an integer, floating-point number, string or
boolean value. The server can decide to coerce each element to the
required type or return an error if an unexpected value is
received. Note that fp16 and bf16 are problematic to communicate explicitly
since there is not a standard fp16/bf16 representation across backends nor
typically the programmatic support to create the fp16/bf16 representation
for a JSON number.

For example, the 2-dimensional matrix:

    [ 1 2
      4 5 ]

Can be represented in its natural format as:

    "data" : [ [ 1, 2 ], [ 4, 5 ] ]

Or in a flattened one-dimensional representation:

    "data" : [ 1, 2, 4, 5 ]

## GRPC

The GRPC API closely follows the concepts defined in the
[HTTP/REST](#httprest) API. A compliant server must implement the
health, metadata, and inference APIs described in this section.

All strings in all contexts are case-sensitive.

The GRPC definition of the service is:

    //
    // Inference Server GRPC endpoints.
    //
    service GRPCInferenceService
    {
      // Check liveness of the inference server.
      rpc ServerLive(ServerLiveRequest) returns (ServerLiveResponse) {}

      // Check readiness of the inference server.
      rpc ServerReady(ServerReadyRequest) returns (ServerReadyResponse) {}

      // Check readiness of a model in the inference server.
      rpc ModelReady(ModelReadyRequest) returns (ModelReadyResponse) {}

      // Get server metadata.
      rpc ServerMetadata(ServerMetadataRequest) returns (ServerMetadataResponse) {}

      // Get model metadata.
      rpc ModelMetadata(ModelMetadataRequest) returns (ModelMetadataResponse) {}

      // Perform inference using a specific model.
      rpc ModelInfer(ModelInferRequest) returns (ModelInferResponse) {}
    }

### Health

A health request is made using the ServerLive, ServerReady, or
ModelReady endpoint. For each of these endpoints errors are indicated
by the google.rpc.Status returned for the request. The OK code
indicates success and other codes indicate failure.

#### Server Live

The ServerLive API indicates if the inference server is able to
receive and respond to metadata and inference requests. The request
and response messages for ServerLive are:

    message ServerLiveRequest {}

    message ServerLiveResponse
    {
      // True if the inference server is live, false if not live.
      bool live = 1;
    }

#### Server Ready

The ServerReady API indicates if the server is ready for
inferencing. The request and response messages for ServerReady are:

    message ServerReadyRequest {}

    message ServerReadyResponse
    {
      // True if the inference server is ready, false if not ready.
      bool ready = 1;
    }

#### Model Ready

The ModelReady API indicates if a specific model is ready for
inferencing. The request and response messages for ModelReady are:

    message ModelReadyRequest
    {
      // The name of the model to check for readiness.
      string name = 1;

      // The version of the model to check for readiness. If not given the
      // server will choose a version based on the model and internal policy.
      string version = 2;
    }

    message ModelReadyResponse
    {
      // True if the model is ready, false if not ready.
      bool ready = 1;
    }

### Server Metadata

The ServerMetadata API provides information about the server. Errors
are indicated by the google.rpc.Status returned for the request. The
OK code indicates success and other codes indicate failure. The
request and response messages for ServerMetadata are:

    message ServerMetadataRequest {}

    message ServerMetadataResponse
    {
      // The server name.
      string name = 1;

      // The server version.
      string version = 2;

      // The extensions supported by the server.
      repeated string extensions = 3;
    }

### Model Metadata

The per-model metadata API provides information about a model. Errors
are indicated by the google.rpc.Status returned for the request. The
OK code indicates success and other codes indicate failure. The
request and response messages for ModelMetadata are:

    message ModelMetadataRequest
    {
      // The name of the model.
      string name = 1;

      // The version of the model to check for readiness. If not given the
      // server will choose a version based on the model and internal policy.
      string version = 2;
    }

    message ModelMetadataResponse
    {
      // Metadata for a tensor.
      message TensorMetadata
      {
        // The tensor name.
        string name = 1;

        // The tensor data type.
        string datatype = 2;

        // The tensor shape. A variable-size dimension is represented
        // by a -1 value.
        repeated int64 shape = 3;
      }

      // The model name.
      string name = 1;

      // The versions of the model available on the server.
      repeated string versions = 2;

      // The model's platform. See Platforms.
      string platform = 3;

      // The model's inputs.
      repeated TensorMetadata inputs = 4;

      // The model's outputs.
      repeated TensorMetadata outputs = 5;
    }

### Inference

The ModelInfer API performs inference using the specified
model. Errors are indicated by the google.rpc.Status returned for the
request. The OK code indicates success and other codes indicate
failure. The request and response messages for ModelInfer are:

    message ModelInferRequest
    {
      // An input tensor for an inference request.
      message InferInputTensor
      {
        // The tensor name.
        string name = 1;

        // The tensor data type.
        string datatype = 2;

        // The tensor shape.
        repeated int64 shape = 3;

        // Optional inference input tensor parameters.
        map<string, InferParameter> parameters = 4;

        // The tensor contents using a data-type format. This field must
        // not be specified if "raw" tensor contents are being used for
        // the inference request.
        InferTensorContents contents = 5;
      }

      // An output tensor requested for an inference request.
      message InferRequestedOutputTensor
      {
        // The tensor name.
        string name = 1;

        // Optional requested output tensor parameters.
        map<string, InferParameter> parameters = 2;
      }

      // The name of the model to use for inferencing.
      string model_name = 1;

      // The version of the model to use for inference. If not given the
      // server will choose a version based on the model and internal policy.
      string model_version = 2;

      // Optional identifier for the request. If specified will be
      // returned in the response.
      string id = 3;

      // Optional inference parameters.
      map<string, InferParameter> parameters = 4;

      // The input tensors for the inference.
      repeated InferInputTensor inputs = 5;

      // The requested output tensors for the inference. Optional, if not
      // specified all outputs produced by the model will be returned.
      repeated InferRequestedOutputTensor outputs = 6;

      // The data contained in an input tensor can be represented in "raw"
      // bytes form or in the repeated type that matches the tensor's data
      // type. To use the raw representation 'raw_input_contents' must be
      // initialized with data for each tensor in the same order as
      // 'inputs'. For each tensor, the size of this content must match
      // what is expected by the tensor's shape and data type. The raw
      // data must be the flattened, one-dimensional, row-major order of
      // the tensor elements without any stride or padding between the
      // elements. Note that the FP16 and BF16 data types must be represented as
      // raw content as there is no specific data type for a 16-bit float type.
      //
      // If this field is specified then InferInputTensor::contents must
      // not be specified for any input tensor.
      repeated bytes raw_input_contents = 7;
    }

    message ModelInferResponse
    {
      // An output tensor returned for an inference request.
      message InferOutputTensor
      {
        // The tensor name.
        string name = 1;

        // The tensor data type.
        string datatype = 2;

        // The tensor shape.
        repeated int64 shape = 3;

        // Optional output tensor parameters.
        map<string, InferParameter> parameters = 4;

        // The tensor contents using a data-type format. This field must
        // not be specified if "raw" tensor contents are being used for
        // the inference response.
        InferTensorContents contents = 5;
      }

      // The name of the model used for inference.
      string model_name = 1;

      // The version of the model used for inference.
      string model_version = 2;

      // The id of the inference request if one was specified.
      string id = 3;

      // Optional inference response parameters.
      map<string, InferParameter> parameters = 4;

      // The output tensors holding inference results.
      repeated InferOutputTensor outputs = 5;

      // The data contained in an output tensor can be represented in
      // "raw" bytes form or in the repeated type that matches the
      // tensor's data type. To use the raw representation 'raw_output_contents'
      // must be initialized with data for each tensor in the same order as
      // 'outputs'. For each tensor, the size of this content must match
      // what is expected by the tensor's shape and data type. The raw
      // data must be the flattened, one-dimensional, row-major order of
      // the tensor elements without any stride or padding between the
      // elements. Note that the FP16 and BF16 data types must be represented as
      // raw content as there is no specific data type for a 16-bit float type.
      //
      // If this field is specified then InferOutputTensor::contents must
      // not be specified for any output tensor.
      repeated bytes raw_output_contents = 6;
    }

### Parameters

The Parameters message describes a “name”/”value” pair, where the
“name” is the name of the parameter and the “value” is a boolean,
integer, or string corresponding to the parameter.

Currently no parameters are defined. As required a future proposal may
define one or more standard parameters to allow portable functionality
across different inference servers. A server can implement
server-specific parameters to provide non-standard capabilities.

    //
    // An inference parameter value.
    //
    message InferParameter
    {
      // The parameter value can be a string, an int64, a boolean
      // or a message specific to a predefined parameter.
      oneof parameter_choice
      {
        // A boolean parameter value.
        bool bool_param = 1;

        // An int64 parameter value.
        int64 int64_param = 2;

        // A string parameter value.
        string string_param = 3;
      }
    }

### Tensor Data

In all representations tensor data must be flattened to a
one-dimensional, row-major order of the tensor elements. Element
values must be given in "linear" order without any stride or padding
between elements.

Using a "raw" representation of tensors with
ModelInferRequest::raw_input_contents and
ModelInferResponse::raw_output_contents will typically allow higher
performance due to the way protobuf allocation and reuse interacts
with GRPC. For example, see https://github.com/grpc/grpc/issues/23231.

An alternative to the "raw" representation is to use
InferTensorContents to represent the tensor data in a format that
matches the tensor's data type.

    //
    // The data contained in a tensor represented by the repeated type
    // that matches the tensor's data type. Protobuf oneof is not used
    // because oneofs cannot contain repeated fields.
    //
    message InferTensorContents
    {
      // Representation for BOOL data type. The size must match what is
      // expected by the tensor's shape. The contents must be the flattened,
      // one-dimensional, row-major order of the tensor elements.
      repeated bool bool_contents = 1;

      // Representation for INT8, INT16, and INT32 data types. The size
      // must match what is expected by the tensor's shape. The contents
      // must be the flattened, one-dimensional, row-major order of the
      // tensor elements.
      repeated int32 int_contents = 2;

      // Representation for INT64 data types. The size must match what
      // is expected by the tensor's shape. The contents must be the
      // flattened, one-dimensional, row-major order of the tensor elements.
      repeated int64 int64_contents = 3;

      // Representation for UINT8, UINT16, and UINT32 data types. The size
      // must match what is expected by the tensor's shape. The contents
      // must be the flattened, one-dimensional, row-major order of the
      // tensor elements.
      repeated uint32 uint_contents = 4;

      // Representation for UINT64 data types. The size must match what
      // is expected by the tensor's shape. The contents must be the
      // flattened, one-dimensional, row-major order of the tensor elements.
      repeated uint64 uint64_contents = 5;

      // Representation for FP32 data type. The size must match what is
      // expected by the tensor's shape. The contents must be the flattened,
      // one-dimensional, row-major order of the tensor elements.
      repeated float fp32_contents = 6;

      // Representation for FP64 data type. The size must match what is
      // expected by the tensor's shape. The contents must be the flattened,
      // one-dimensional, row-major order of the tensor elements.
      repeated double fp64_contents = 7;

      // Representation for BYTES data type. The size must match what is
      // expected by the tensor's shape. The contents must be the flattened,
      // one-dimensional, row-major order of the tensor elements.
      repeated bytes bytes_contents = 8;
    }

## Platforms

A platform is a string indicating a DL/ML framework or
backend. Platform is returned as part of the response to a
[Model Metadata](#model-metadata) request but is information only. The
proposed inference APIs are generic relative to the DL/ML framework
used by a model and so a client does not need to know the platform of
a given model to use the API. Platform names use the format
“<project>_<format>”. The following platform names are allowed:

* tensorrt_plan : A TensorRT model encoded as a serialized engine or “plan”.
* tensorflow_graphdef : A TensorFlow model encoded as a GraphDef.
* tensorflow_savedmodel : A TensorFlow model encoded as a SavedModel.
* onnx_onnxv1 : A ONNX model encoded for ONNX Runtime.
* pytorch_torchscript : A PyTorch model encoded as TorchScript.
* mxnet_mxnet: An MXNet model
* caffe2_netdef : A Caffe2 model encoded as a NetDef.

## Tensor Data Types

Tensor data types are shown in the following table along with the size
of each type, in bytes.


| Data Type | Size (bytes) |
| --------- | ------------ |
| BOOL      | 1            |
| UINT8     | 1            |
| UINT16    | 2            |
| UINT32    | 4            |
| UINT64    | 8            |
| INT8      | 1            |
| INT16     | 2            |
| INT32     | 4            |
| INT64     | 8            |
| FP16      | 2            |
| FP32      | 4            |
| FP64      | 8            |
| BYTES     | Variable (max 2<sup>32</sup>) |
| BF16      | 2            |

import numpy as np
import requests
import pandas as pd
import plotly.graph_objects as go
from IPython.display import Markdown, display


def getFeatures(X, cmap):
    return pd.DataFrame(X).replace(cmap).values.squeeze().tolist()


def predict(X, name, ds, svc_hostname, cluster_ip):
    formData = {"instances": X}
    headers = {"Host": svc_hostname}
    res = requests.post(
        "http://" + cluster_ip + "/v1/models/" + name + ":predict",
        json=formData,
        headers=headers,
    )
    if res.status_code == 200:
        return ds.target_names[np.array(res.json()["predictions"])[0]]
    else:
        print("Failed with ", res.status_code)
        return []


def explain(X, name, svc_hostname, cluster_ip):
    formData = {"instances": X}
    headers = {"Host": svc_hostname}
    res = requests.post(
        "http://" + cluster_ip + "/v1/models/" + name + ":explain",
        json=formData,
        headers=headers,
    )
    if res.status_code == 200:
        return res.json()
    else:
        print("Failed with ", res.status_code)
        return []


def show_bar(X, labels, title):
    fig = go.Figure(go.Bar(x=X, y=labels, orientation="h", width=[0.5]))
    fig.update_layout(
        autosize=False,
        width=700,
        height=300,
        xaxis=dict(range=[0, 1]),
        title_text=title,
        font=dict(family="Courier New, monospace", size=18, color="#7f7f7f"),
    )
    fig.show()


def show_feature_coverage(exp):
    data = []
    for idx, name in enumerate(exp["anchor"]):
        data.append(go.Bar(name=name, x=["coverage"], y=[exp["raw"]["coverage"][idx]]))
    fig = go.Figure(data=data)
    fig.update_layout(yaxis=dict(range=[0, 1]))
    fig.show()


def show_anchors(names):
    display(Markdown("# Explanation:"))
    display(Markdown("## {}".format(names)))


def show_examples(exp, fidx, ds, covered=True):
    if covered:
        cname = "covered_true"
        display(
            Markdown(
                "## Examples covered by Anchors: {}".format(exp["anchor"][0 : fidx + 1])
            )
        )
    else:
        cname = "covered_false"
        display(
            Markdown(
                "## Examples not covered by Anchors: {}".format(
                    exp["anchor"][0 : fidx + 1]
                )
            )
        )
    if "feature_names" in ds:
        return pd.DataFrame(
            exp["raw"]["examples"][fidx][cname], columns=ds.feature_names
        )
    else:
        return pd.DataFrame(exp["raw"]["examples"][fidx][cname])


def show_prediction(prediction):
    display(Markdown("## Prediction: {}".format(prediction)))


def show_row(X, ds):
    display(pd.DataFrame(X, columns=ds.feature_names))

