//! Client-side CEL validation generated by `#[kube(cel)]` / `#[x_kube(cel)]`.
//!
//! Run with: `cargo run --example crd_derive_cel --features cel`
//!
//! The same CEL rules the apiserver enforces server-side are evaluated locally here, without a
//! cluster. The root `#[kube(cel)]` generates `Resource::validate_cel(&self)` /
//! `validate_cel_update(&self, old)`; `#[x_kube(cel)]` generates a static
//! `Spec::validate_cel(value, old)` you can call on a fragment.
use kube::{CustomResource, KubeSchema};
use serde::{Deserialize, Serialize};

/// A toy autoscaler spec with CEL constraints.
///
/// - Root rule (`self` is the whole object): `minReplicas <= maxReplicas`.
/// - Spec-scoped rule (`self` is the spec): mirror of the same bound, usable on the spec alone.
/// - Field rules: `minReplicas >= 0`, and `tier` is immutable across updates (`self == oldSelf`).
#[derive(CustomResource, KubeSchema, Serialize, Deserialize, Clone, Debug)]
#[kube(
    group = "example.kube.rs",
    version = "v1",
    kind = "Autoscaler",
    namespaced,
    cel,
    validation = "self.spec.minReplicas <= self.spec.maxReplicas"
)]
#[x_kube(cel, validation = "self.minReplicas <= self.maxReplicas")]
#[serde(rename_all = "camelCase")]
struct AutoscalerSpec {
    #[x_kube(validation = "self >= 0")]
    min_replicas: i32,
    max_replicas: i32,
    #[x_kube(validation = "self == oldSelf")]
    tier: String,
}

fn main() {
    // Root: a valid resource passes.
    let valid = Autoscaler::new("web", AutoscalerSpec {
        min_replicas: 1,
        max_replicas: 5,
        tier: "standard".into(),
    });
    println!("valid.validate_cel() -> {:?}", valid.validate_cel());
    assert!(valid.validate_cel().is_ok());

    // Root: min > max violates the creation rule.
    let invalid = Autoscaler::new("web", AutoscalerSpec {
        min_replicas: 9,
        max_replicas: 5,
        tier: "standard".into(),
    });
    println!("invalid.validate_cel() -> {:?}", invalid.validate_cel());
    assert!(invalid.validate_cel().is_err());

    // Root update: changing the immutable `tier` violates the transition rule.
    let changed = Autoscaler::new("web", AutoscalerSpec {
        min_replicas: 1,
        max_replicas: 5,
        tier: "premium".into(),
    });
    println!(
        "changed.validate_cel_update(&valid) -> {:?}",
        changed.validate_cel_update(&valid)
    );
    assert!(changed.validate_cel_update(&valid).is_err());

    // Sub-struct: validate a serialized spec fragment directly, no resource needed.
    let fragment = serde_json::json!({"minReplicas": 3, "maxReplicas": 1, "tier": "standard"});
    let result = AutoscalerSpec::validate_cel(&fragment, None);
    println!("AutoscalerSpec::validate_cel(fragment) -> {result:?}");
    assert!(result.is_err());

    println!("all CEL validations behaved as expected");
}

//! An example of how to define a custom JSON schema for a custom resource (definition).

use std::borrow::Cow;

use kube::CustomResourceExt;
use kube_derive::CustomResource;
use schemars::{JsonSchema, json_schema};
use serde::{Deserialize, Serialize};

/// CustomResource with manually implemented `JsonSchema`
#[derive(CustomResource, Serialize, Deserialize, Debug, Clone)]
#[kube(
    group = "clux.dev",
    version = "v1",
    kind = "Bar",
    namespaced,
    schema = "manual"
)]
pub struct MyBar {
    bars: u32,
}

impl JsonSchema for Bar {
    fn schema_name() -> Cow<'static, str> {
        "Bar".into()
    }

    fn json_schema(__gen: &mut schemars::generate::SchemaGenerator) -> schemars::Schema {
        json_schema!({
            "properties": {
                "spec": {
                    "properties": {
                        "bars": {
                            "type": "integer"
                        }
                    },
                    "required": [
                        "bars"
                    ],
                    "type": "object"
                }
            },
            "required": [
                "spec"
            ],
            "title": "Bar"
        })
    }
}

fn main() {
    let crd = Bar::crd();
    println!("{}", serde_json::to_string(&crd).unwrap());
}

// Verify CustomResource derivable still
#[test]
fn verify_bar_is_a_custom_resource() {
    use kube::Resource;
    use static_assertions::assert_impl_all;

    println!("Kind {}", Bar::kind(&()));
    let bar = Bar::new("five", MyBar { bars: 5 });
    println!("Spec: {:?}", bar.spec);
    assert_impl_all!(Bar: kube::Resource, JsonSchema);

    let crd = Bar::crd();
    for v in crd.spec.versions {
        assert!(v.schema.unwrap().open_api_v3_schema.is_some());
    }
}

//! An example of a multi-version derived custom resource.

use k8s_openapi::apiextensions_apiserver::pkg::apis::apiextensions::v1::CustomResourceDefinition;
use kube::{
    Client, CustomResource, CustomResourceExt, ResourceExt,
    api::{Api, Patch, PatchParams},
    core::crd::merge_crds,
    runtime::wait::{await_condition, conditions},
};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use tracing::*;

mod v1 {
    use super::*;
    // spec that is forwards compatible with v2 (can upgrade by truncating)
    #[derive(CustomResource, Serialize, Deserialize, Default, Debug, Clone, JsonSchema)]
    #[kube(
        group = "kube.rs",
        version = "v1",
        kind = "ManyDerive",
        status = "ManyDeriveStatus",
        namespaced
    )]
    pub struct ManyDeriveSpec {
        pub name: String,
        pub oldprop: u32,
    }
    #[derive(Serialize, Deserialize, Default, Debug, Clone, JsonSchema)]
    pub struct ManyDeriveStatus {
        pub condition: Option<bool>,
    }
}
mod v2 {
    // spec that is NOT backwards compatible with v1 (cannot retrieve oldprop if truncated)
    use super::*;
    #[derive(CustomResource, Serialize, Deserialize, Default, Debug, Clone, JsonSchema)]
    #[kube(
        group = "kube.rs",
        version = "v2",
        kind = "ManyDerive",
        namespaced,
        status = "v1::ManyDeriveStatus" // cross-referencing from v1 module
    )]
    pub struct ManyDeriveSpec {
        pub name: String,
        pub extra: Option<String>,
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();

    let client = Client::try_default().await?;
    let ssapply = PatchParams::apply("crd_derive_multi").force();

    let crd1 = v1::ManyDerive::crd();
    let crd2 = v2::ManyDerive::crd();
    let all_crds = vec![crd1.clone(), crd2.clone()];

    // apply schema where v1 is the stored version
    apply_crd(client.clone(), merge_crds(all_crds.clone(), "v1")?).await?;

    // create apis
    let v1api: Api<v1::ManyDerive> = Api::default_namespaced(client.clone());
    let v2api: Api<v2::ManyDerive> = Api::default_namespaced(client.clone());

    // create a v1 version
    let v1m = v1::ManyDerive::new("old", v1::ManyDeriveSpec {
        name: "i am old".into(),
        oldprop: 5,
    });
    let oldvarv1 = v1api.patch("old", &ssapply, &Patch::Apply(&v1m)).await?;
    info!("old instance on v1: {:?}", oldvarv1.spec);
    let oldvarv2 = v2api.get("old").await?;
    info!("old instance on v2 truncates: {:?}", oldvarv2.spec);

    // create a v2 version
    let v2m = v2::ManyDerive::new("new", v2::ManyDeriveSpec {
        name: "i am new".into(),
        extra: Some("hi".into()),
    });
    let newvarv2 = v2api.patch("new", &ssapply, &Patch::Apply(&v2m)).await?;
    info!("new instance on v2 is force downgraded: {:?}", newvarv2.spec); // no extra field
    let cannot_fetch_as_old = v1api.get("new").await.unwrap_err();
    info!("cannot fetch new on v1: {:?}", cannot_fetch_as_old);

    // apply schema upgrade
    apply_crd(client.clone(), merge_crds(all_crds, "v2")?).await?;

    // nothing changed with existing objects without conversion
    //let oldvarv1_upg = v1api.get("old").await?;
    //info!("old instance unchanged on v1: {:?}", oldvarv1_upg.spec);
    //let oldvarv2_upg = v2api.get("old").await?;
    //info!("old instance unchanged on v2: {:?}", oldvarv2_upg.spec);

    // re-apply new now that v2 is stored gives us the extra properties
    let newvarv2_2 = v2api.patch("new", &ssapply, &Patch::Apply(&v2m)).await?;
    info!("new on v2 correct on reapply to v2: {:?}", newvarv2_2.spec);

    // note we can apply old versions without them being truncated to the v2 schema
    // in our case this means we cannot fetch them with our v1 schema (breaking change to not have oldprop)
    let v1m2 = v1::ManyDerive::new("old", v1::ManyDeriveSpec {
        name: "i am old2".into(),
        oldprop: 5,
    });
    let v1err = v1api
        .patch("old", &ssapply, &Patch::Apply(&v1m2))
        .await
        .unwrap_err();
    info!("cannot get old on v1 anymore: {:?}", v1err); // mandatory field oldprop truncated
    // ...but the change is still there:
    let old_still_there = v2api.get("old").await?;
    assert_eq!(old_still_there.spec.name, "i am old2");

    cleanup(client.clone()).await?;
    Ok(())
}

async fn apply_crd(client: Client, crd: CustomResourceDefinition) -> anyhow::Result<()> {
    let crds: Api<CustomResourceDefinition> = Api::all(client.clone());
    info!("Creating crd: {}", serde_saphyr::to_string(&crd)?);
    let ssapply = PatchParams::apply("crd_derive_multi").force();
    crds.patch("manyderives.kube.rs", &ssapply, &Patch::Apply(&crd))
        .await?;
    let establish = await_condition(
        crds.clone(),
        "manyderives.kube.rs",
        conditions::is_crd_established(),
    );
    let _ = tokio::time::timeout(std::time::Duration::from_secs(10), establish).await?;
    Ok(())
}

async fn cleanup(client: Client) -> anyhow::Result<()> {
    let crds: Api<CustomResourceDefinition> = Api::all(client.clone());
    let obj = crds.delete("manyderives.kube.rs", &Default::default()).await?;
    if let either::Either::Left(o) = obj {
        let uid = o.uid().unwrap();
        await_condition(crds, "manyderives.kube.rs", conditions::is_deleted(&uid)).await?;
    }
    Ok(())
}

//! An example of how to disable the JSON schema for a custom resource entirely.

use k8s_openapi::apiextensions_apiserver::pkg::apis::apiextensions::v1::{
    CustomResourceDefinition, CustomResourceValidation, JSONSchemaProps,
};
use kube_derive::CustomResource;
use serde::{Deserialize, Serialize};

/// CustomResource with manually implemented schema
///
/// Normally you would do this by deriving JsonSchema or manually implementing it / parts of it.
/// But here, we simply drop in a valid schema from a string and avoid schemars from the dependency tree entirely.
#[derive(CustomResource, Serialize, Deserialize, Debug, Clone)]
#[kube(
    group = "clux.dev",
    version = "v1",
    kind = "Bar",
    namespaced,
    schema = "disabled"
)]
pub struct MyBar {
    bars: u32,
}

const MANUAL_SCHEMA: &str = r#"
type: object
properties:
  spec:
    type: object
    properties:
      bars:
        type: int
    required:
    - bars
"#;

impl Bar {
    fn crd_with_manual_schema() -> CustomResourceDefinition {
        use kube::CustomResourceExt;
        let schema: JSONSchemaProps = serde_saphyr::from_str(MANUAL_SCHEMA).expect("invalid schema");

        let mut crd = <Self as CustomResourceExt>::crd();
        crd.spec.versions.iter_mut().for_each(|v| {
            v.schema = Some(CustomResourceValidation {
                open_api_v3_schema: Some(schema.clone()),
            })
        });
        crd
    }
}

fn main() {
    tracing_subscriber::fmt::init();
    let crd = Bar::crd_with_manual_schema();
    println!("{}", serde_saphyr::to_string(&crd).unwrap());
}

// Verify CustomResource derivable still
#[test]
fn verify_bar_is_a_custom_resource() {
    use kube::Resource;
    use schemars::JsonSchema; // only for ensuring it's not implemented
    use static_assertions::{assert_impl_all, assert_not_impl_any};

    println!("Kind {}", Bar::kind(&()));
    let bar = Bar::new("five", MyBar { bars: 5 });
    println!("Spec: {:?}", bar.spec);
    assert_impl_all!(Bar: kube::Resource);
    assert_not_impl_any!(MyBar: JsonSchema); // but no schemars schema implemented

    let crd = Bar::crd_with_manual_schema();
    for v in crd.spec.versions {
        assert!(v.schema.unwrap().open_api_v3_schema.is_some());
    }
}

//! An example of how to derive the JSOn schema for a custom resource.

use anyhow::{Result, anyhow};
use futures::{StreamExt, TryStreamExt};
use k8s_openapi::apiextensions_apiserver::pkg::apis::apiextensions::v1::CustomResourceDefinition;
use kube::{
    Client, CustomResource, CustomResourceExt, KubeSchema,
    api::{
        Api, ApiResource, DeleteParams, DynamicObject, GroupVersionKind, Patch, PatchParams, PostParams,
        WatchEvent, WatchParams,
    },
    runtime::wait::{await_condition, conditions},
};
use schemars::json_schema;
use serde::{Deserialize, Serialize};

// This example shows how the generated schema affects defaulting and validation.
// The integration test `crd_schema_test` in `kube-derive` contains the full CRD JSON generated from this struct.
//
// References:
// - https://kubernetes.io/docs/tasks/extend-kubernetes/custom-resources/custom-resource-definitions/#defaulting
// - https://kubernetes.io/docs/tasks/extend-kubernetes/custom-resources/custom-resource-definitions/#defaulting-and-nullable

/// Our own custom resource
#[derive(CustomResource, KubeSchema, Serialize, Deserialize, Default, Debug, PartialEq, Eq, Clone)]
#[kube(
    group = "clux.dev",
    version = "v1",
    kind = "Foo",
    namespaced,
    derive = "PartialEq",
    derive = "Default",
    validation = "self.metadata.name != 'forbidden'"
)]
#[serde(rename_all = "camelCase")]
#[x_kube(validation = "self.nonNullable == oldSelf.nonNullable")]
pub struct FooSpec {
    // Non-nullable without default is required.
    //
    // There shouldn't be any ambiguity here.
    non_nullable: String,

    // Non-nullable with default value.
    //
    // Serializing will work as expected because the field cannot be `None`.
    //
    // When deserializing a response from the server, the field should always be a string because
    // the field is non-nullable and the server sets the value to the default specified in the schema.
    //
    // When deserializing some input, the default value will be set if missing.
    // However, if `null` is specified, `serde` will panic.
    // The server prunes `null` for non-nullable field since 1.20 and the default is applied.
    // To match the server's behavior exactly, we can use a custom deserializer.
    #[serde(default = "default_value")]
    non_nullable_with_default: String,

    // Nullable without default, skipping None.
    //
    // By skipping to serialize, the field won't be present in the object.
    // If serialized as `null` (next field), the object will have the field set to `null`.
    //
    // Deserializing works as expected either way. `None` if it's missing or `null`.
    #[serde(skip_serializing_if = "Option::is_none")]
    nullable_skipped: Option<String>,
    // Nullable without default, not skipping None.
    nullable: Option<String>,

    // Nullable with default, skipping None.
    //
    // By skipping to serialize when `None`, the server will set the the default value specified in the schema.
    // If serialized as `null`, the server will conserve it and the defaulting does not happen (since 1.20).
    //
    // When deserializing, the default value is used only when it's missing (`null` is `None`).
    // This is consistent with how the server handles it since 1.20.
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default = "default_nullable")]
    nullable_skipped_with_default: Option<String>,

    // Nullable with default, not skipping None.
    //
    // The default value won't be used unless missing, so this will set the value to `null`.
    // If the resource is created with `kubectl` and if this field was missing, defaulting will happen.
    #[serde(default = "default_nullable")]
    nullable_with_default: Option<String>,

    /// Default listable field
    #[serde(default)]
    default_listable: Vec<u32>,

    // Listable field with specified 'set' merge strategy
    #[serde(default)]
    #[schemars(schema_with = "set_listable_schema")]
    set_listable: Vec<u32>,

    // Field with CEL validation
    #[serde(default = "default_legal")]
    #[x_kube(
        validation = Rule::new("self != 'illegal'").message(Message::Expression("'string cannot be illegal'".into())).reason(Reason::FieldValueForbidden),
        validation = Rule::new("self != 'not legal'").reason(Reason::FieldValueInvalid),
    )]
    cel_validated: Option<String>,

    /// Immutable field that uses optionalOldSelf
    #[serde(default)]
    #[x_kube(
        validation = Rule::new("oldSelf.optMap(o, o == self).orValue(true)").optional_old_self(true).message("Immutable after creation")
    )]
    immutable: Option<String>,

    #[x_kube(validation = Rule::new("self == oldSelf").message("is immutable"))]
    foo_sub_spec: Option<FooSubSpec>,

    #[serde(default = "FooSpec::default_value")]
    associated_default: bool,
}

/// A part of our custom resource
#[derive(KubeSchema, Serialize, Deserialize, Default, Debug, PartialEq, Eq, Clone)]
pub struct FooSubSpec {
    /// Heterogenous CEL rule set
    #[x_kube(validation = "self != 'not legal'", validation = Rule::new("self != 'not that'"))]
    #[x_kube(validation = ("self != 'also not that'", "some pretty good reason"))]
    field: String,

    other: Option<String>,
}

impl FooSpec {
    fn default_value() -> bool {
        true
    }
}

// https://kubernetes.io/docs/reference/using-api/server-side-apply/#merge-strategy
fn set_listable_schema(_: &mut schemars::generate::SchemaGenerator) -> schemars::Schema {
    json_schema!({
        "type": "array",
        "items": {
            "format": "u32",
            "minimum": 0,
            "type": "integer"
        },
        "x-kubernetes-list-type": "set"
    })
}

fn default_value() -> String {
    "default_value".into()
}

fn default_legal() -> Option<String> {
    Some("legal".into())
}

fn default_nullable() -> Option<String> {
    Some("default_nullable".into())
}

#[tokio::main]
async fn main() -> Result<()> {
    // Show the generated CRD
    println!("Foo CRD:\n{}\n", serde_saphyr::to_string(&Foo::crd())?);

    // Creating CRD v1 works as expected.
    println!("Creating CRD v1");
    let client = Client::try_default().await?;
    delete_crd(client.clone()).await?;
    assert!(create_crd(client.clone()).await.is_ok());

    // Test creating Foo resource.
    let foos = Api::<Foo>::default_namespaced(client.clone());
    // Create with defaults using typed Api first.
    // `non_nullable` and `non_nullable_with_default` are set to empty strings.
    // Nullables defaults to `None` and only sent if it's not configured to skip.
    let bar = Foo::new("bar", FooSpec { ..FooSpec::default() });
    let bar = foos.create(&PostParams::default(), &bar).await?;
    assert_eq!(bar.spec, FooSpec {
        // Nonnullable without default is required.
        non_nullable: String::default(),
        // Defaulting didn't happen because an empty string was sent.
        non_nullable_with_default: String::default(),
        // `nullable_skipped` field does not exist in the object (see below).
        nullable_skipped: None,
        // `nullable` field exists in the object (see below).
        nullable: None,
        // Defaulting happened because serialization was skipped.
        nullable_skipped_with_default: default_nullable(),
        // Defaulting did not happen because `null` was sent.
        // Deserialization does not apply the default either.
        nullable_with_default: None,
        // Empty listables to be patched in later
        default_listable: Default::default(),
        set_listable: Default::default(),
        cel_validated: Default::default(),
        immutable: Default::default(),
        foo_sub_spec: Default::default(),
        associated_default: Default::default(),
    });

    // Set up dynamic resource to test using raw values.
    let gvk = GroupVersionKind::gvk("clux.dev", "v1", "Foo");
    let api_resource = ApiResource::from_gvk(&gvk);
    let dynapi: Api<DynamicObject> = Api::default_namespaced_with(client.clone(), &api_resource);

    // Test that skipped nullable field without default is not defined.
    let val = dynapi.get("bar").await?.data;
    println!("{:?}", val["spec"]);
    // `nullable_skipped` field does not exist, but `nullable` does.
    let spec = val["spec"].as_object().unwrap();
    assert!(!spec.contains_key("nullable_skipped"));
    assert!(spec.contains_key("nullable"));

    // Test defaulting of `non_nullable_with_default` field
    let data = DynamicObject::new("baz", &api_resource).data(serde_json::json!({
        "spec": {
            "nonNullable": "a required field",
            // `non_nullable_with_default` field is missing

            // listable values to patch later to verify merge strategies
            "defaultListable": vec![2],
            "setListable": vec![2],
        }
    }));
    let val = dynapi.create(&PostParams::default(), &data).await?.data;
    println!("{:?}", val["spec"]);
    // Defaulting happened for non-nullable field
    assert_eq!(val["spec"]["nonNullableWithDefault"], default_value());

    // Listables
    assert_eq!(serde_json::to_string(&val["spec"]["defaultListable"])?, "[2]");
    assert_eq!(serde_json::to_string(&val["spec"]["setListable"])?, "[2]");
    assert_eq!(serde_json::to_string(&val["spec"]["celValidated"])?, "\"legal\"");
    assert_eq!(serde_json::to_string(&val["spec"]["associatedDefault"])?, "true");

    // Missing required field (non-nullable without default) is an error
    let data = DynamicObject::new("qux", &api_resource).data(serde_json::json!({
        "spec": {}
    }));
    let res = dynapi.create(&PostParams::default(), &data).await;
    assert!(res.is_err());
    match res.err() {
        Some(kube::Error::Api(err)) => {
            assert_eq!(err.code, 422);
            assert_eq!(err.reason, "Invalid");
            assert!(err.is_failure());
            assert!(err.message.contains("clux.dev \"qux\" is invalid"));
            assert!(err.message.contains("spec.nonNullable: Required value"));
        }
        _ => panic!(),
    }

    // Resource level metadata validations check
    let forbidden = Foo::new("forbidden", FooSpec { ..FooSpec::default() });
    let res = foos.create(&PostParams::default(), &forbidden).await;
    assert!(res.is_err());

    // Test the manually specified merge strategy
    let ssapply = PatchParams::apply("crd_derive_schema_example").force();
    let patch = serde_json::json!({
        "apiVersion": "clux.dev/v1",
        "kind": "Foo",
        "spec": {
            "defaultListable": vec![3],
            "setListable": vec![3]
        }
    });
    let pres = foos.patch("baz", &ssapply, &Patch::Apply(patch)).await?;
    assert_eq!(pres.spec.default_listable, vec![3]);
    assert_eq!(pres.spec.set_listable, vec![2, 3]);
    println!("{:?}", serde_json::to_value(pres.spec));

    // cel validation triggers:
    let cel_patch = serde_json::json!({
        "apiVersion": "clux.dev/v1",
        "kind": "Foo",
        "spec": {
            "celValidated": Some("illegal")
        }
    });
    let cel_res = foos.patch("baz", &ssapply, &Patch::Apply(cel_patch)).await;
    assert!(cel_res.is_err());
    match cel_res.err() {
        Some(kube::Error::Api(err)) => {
            assert_eq!(err.code, 422);
            assert_eq!(err.reason, "Invalid");
            assert!(err.is_failure());
            assert!(err.message.contains("Foo.clux.dev \"baz\" is invalid"));
            assert!(err.message.contains("spec.celValidated: Forbidden"));
            assert!(err.message.contains("string cannot be illegal"));
        }
        _ => panic!(),
    }

    // cel validation triggers:
    let cel_patch = serde_json::json!({
        "apiVersion": "clux.dev/v1",
        "kind": "Foo",
        "spec": {
            "celValidated": Some("not legal")
        }
    });
    let cel_res = foos.patch("baz", &ssapply, &Patch::Apply(cel_patch)).await;
    assert!(cel_res.is_err());
    match cel_res.err() {
        Some(kube::Error::Api(err)) => {
            assert_eq!(err.code, 422);
            assert_eq!(err.reason, "Invalid");
            assert!(err.is_failure());
            assert!(err.message.contains("Foo.clux.dev \"baz\" is invalid"));
            assert!(err.message.contains("spec.celValidated: Invalid value"));
            assert!(err.message.contains("failed rule: self != 'not legal'"));
        }
        _ => panic!(),
    }

    let cel_patch = serde_json::json!({
        "apiVersion": "clux.dev/v1",
        "kind": "Foo",
        "spec": {
            "fooSubSpec": {
                "field": Some("not legal"),
            }
        }
    });
    let cel_res = foos.patch("baz", &ssapply, &Patch::Apply(cel_patch)).await;
    assert!(cel_res.is_err());
    match cel_res.err() {
        Some(kube::Error::Api(err)) => {
            assert_eq!(err.code, 422);
            assert_eq!(err.reason, "Invalid");
            assert!(err.is_failure());
            assert!(err.message.contains("Foo.clux.dev \"baz\" is invalid"));
            assert!(err.message.contains("spec.fooSubSpec.field: Invalid value"));
            assert!(err.message.contains("failed rule: self != 'not legal'"));
        }
        _ => panic!(),
    }

    let cel_patch = serde_json::json!({
        "apiVersion": "clux.dev/v1",
        "kind": "Foo",
        "spec": {
            "fooSubSpec": {
                "field": Some("also not that"),
            }
        }
    });
    let cel_res = foos.patch("baz", &ssapply, &Patch::Apply(cel_patch)).await;
    assert!(cel_res.is_err());
    match cel_res.err() {
        Some(kube::Error::Api(err)) => {
            assert_eq!(err.code, 422);
            assert_eq!(err.reason, "Invalid");
            assert!(err.is_failure());
            assert!(err.message.contains("Foo.clux.dev \"baz\" is invalid"));
            assert!(err.message.contains("spec.fooSubSpec.field: Invalid value"));
            assert!(err.message.contains("some pretty good reason"));
        }
        _ => panic!(),
    }

    let cel_patch = serde_json::json!({
        "apiVersion": "clux.dev/v1",
        "kind": "Foo",
        "spec": {
            "fooSubSpec": {
                "field": Some("legal"),
            }
        }
    });
    let cel_res = foos.patch("baz", &ssapply, &Patch::Apply(cel_patch)).await;
    assert!(cel_res.is_ok());

    let cel_patch = serde_json::json!({
        "apiVersion": "clux.dev/v1",
        "kind": "Foo",
        "spec": {
            "fooSubSpec": {
                "field": Some("legal"),
                "other": "different",
            }
        }
    });
    let cel_res = foos.patch("baz", &ssapply, &Patch::Apply(cel_patch)).await;
    assert!(cel_res.is_err());
    match cel_res.err() {
        Some(kube::Error::Api(err)) => {
            assert_eq!(err.code, 422);
            assert_eq!(err.reason, "Invalid");
            assert!(err.is_failure());
            assert!(err.message.contains("Foo.clux.dev \"baz\" is invalid"));
            assert!(err.message.contains("spec.fooSubSpec: Invalid value"));
            assert!(err.message.contains("Immutable after creation") || err.message.contains("is immutable"));
        }
        _ => panic!(),
    }

    // cel validation happy:
    let cel_patch_ok = serde_json::json!({
        "apiVersion": "clux.dev/v1",
        "kind": "Foo",
        "spec": {
            "celValidated": Some("legal")
        }
    });
    foos.patch("baz", &ssapply, &Patch::Apply(cel_patch_ok)).await?;

    // all done
    delete_crd(client.clone()).await?;
    Ok(())
}

// Create CRD and wait for it to be ready.
async fn create_crd(client: Client) -> Result<CustomResourceDefinition> {
    let api = Api::<CustomResourceDefinition>::all(client);
    api.create(&PostParams::default(), &Foo::crd()).await?;

    // Wait until it's accepted and established by the api-server
    println!("Waiting for the api-server to accept the CRD");
    let establish = await_condition(api.clone(), "foos.clux.dev", conditions::is_crd_established());
    let _ = tokio::time::timeout(std::time::Duration::from_secs(10), establish).await?;

    // It's served by the api - get it and return it
    let crd = api.get("foos.clux.dev").await?;
    Ok(crd)
}

// Delete the CRD if it exists and wait until it's deleted.
async fn delete_crd(client: Client) -> Result<()> {
    let api = Api::<CustomResourceDefinition>::all(client);
    if api.get("foos.clux.dev").await.is_ok() {
        api.delete("foos.clux.dev", &DeleteParams::default()).await?;

        // Wait until deleted
        let timeout_secs = 15;
        let wp = WatchParams::default()
            .fields("metadata.name=foos.clux.dev")
            .timeout(timeout_secs);
        let mut stream = api.watch(&wp, "0").await?.boxed_local();
        while let Some(status) = stream.try_next().await? {
            if let WatchEvent::Deleted(_) = status {
                return Ok(());
            }
        }
        Err(anyhow!(format!("CRD not deleted after {timeout_secs} seconds")))
    } else {
        Ok(())
    }
}

//! An example of how to keep an up-to-date reflector of CustomResourceDefinitions (CRDs) in memory
//! and periodically read its state.

use futures::{StreamExt, TryStreamExt};
use k8s_openapi::apiextensions_apiserver::pkg::apis::apiextensions::v1::CustomResourceDefinition;
use tracing::*;

use kube::{
    Client, CustomResource, CustomResourceExt,
    api::{Api, Patch, PatchParams, ResourceExt},
    runtime::{WatchStreamExt, reflector, watcher},
};

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Our custom resource
#[derive(CustomResource, Deserialize, Serialize, Clone, Debug, JsonSchema)]
#[kube(group = "clux.dev", version = "v1", kind = "Foo", namespaced)]
pub struct FooSpec {
    name: String,
    info: String,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    // 0. Ensure the CRD is installed (you probably just want to do this on CI)
    // (crd file can be created by piping `Foo::crd`'s yaml ser to kubectl apply)
    let crds: Api<CustomResourceDefinition> = Api::all(client.clone());
    info!("Creating crd: {}", serde_saphyr::to_string(&Foo::crd())?);
    let ssapply = PatchParams::apply("crd_reflector_example").force();
    crds.patch("foos.clux.dev", &ssapply, &Patch::Apply(Foo::crd()))
        .await?;
    tokio::time::sleep(std::time::Duration::from_secs(2)).await; // wait for k8s to deal with it

    // 1. Run a reflector against the installed CRD
    let (reader, writer) = reflector::store::<Foo>();

    let foos: Api<Foo> = Api::default_namespaced(client);
    let wc = watcher::Config::default().any_semantic();
    let mut stream = watcher(foos, wc)
        .default_backoff()
        .reflect(writer)
        .applied_objects()
        .boxed();

    tokio::spawn(async move {
        reader.wait_until_ready().await.unwrap();
        loop {
            // Periodically read our state
            // while this runs you can kubectl apply -f crd-baz.yaml or crd-qux.yaml and see it works
            tokio::time::sleep(std::time::Duration::from_secs(5)).await;
            let crds = reader.state().iter().map(|r| r.name_any()).collect::<Vec<_>>();
            info!("Current crds: {:?}", crds);
        }
    });
    while let Some(event) = stream.try_next().await? {
        info!("saw {}", event.name_any());
    }
    Ok(())
}

