//! Custom client example with TraceLayer.

use http::{Request, Response};
use hyper::body::Incoming;
use hyper_util::rt::TokioExecutor;
use k8s_openapi::api::core::v1::Pod;
use std::time::Duration;
use tower::{BoxError, ServiceBuilder};
use tower_http::{decompression::DecompressionLayer, trace::TraceLayer};
use tracing::{Span, *};

use kube::{
    Api, Client, Config, ResourceExt,
    client::{Body, ConfigExt},
};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();

    let config = Config::infer().await?;
    let https = config.rustls_https_connector()?;
    let service = ServiceBuilder::new()
        .layer(config.base_uri_layer())
        // showcase rate limiting; max 10rps, and 4 concurrent
        .layer(tower::limit::RateLimitLayer::new(10, Duration::from_secs(1)))
        .layer(tower::limit::ConcurrencyLimitLayer::new(4))
        // Add `DecompressionLayer` to make request headers interesting.
        .layer(DecompressionLayer::new())
        .option_layer(config.auth_layer()?)
        .layer(
            // Attribute names follow [Semantic Conventions].
            // [Semantic Conventions]: https://github.com/open-telemetry/opentelemetry-specification/blob/main/specification/trace/semantic_conventions/http.md#http-client
            TraceLayer::new_for_http()
                .make_span_with(|request: &Request<Body>| {
                    tracing::debug_span!(
                        "HTTP",
                        http.method = %request.method(),
                        http.url = %request.uri(),
                        http.status_code = tracing::field::Empty,
                        otel.name = %format!("HTTP {}", request.method()),
                        otel.kind = "client",
                        otel.status_code = tracing::field::Empty,
                    )
                })
                .on_request(|request: &Request<Body>, _span: &Span| {
                    tracing::debug!("payload: {:?} headers: {:?}", request.body(), request.headers())
                })
                .on_response(|response: &Response<Incoming>, latency: Duration, span: &Span| {
                    let status = response.status();
                    span.record("http.status_code", status.as_u16());
                    if status.is_client_error() || status.is_server_error() {
                        span.record("otel.status_code", "ERROR");
                    }
                    tracing::debug!("finished in {}ms", latency.as_millis())
                }),
        )
        .map_err(BoxError::from)
        .service(hyper_util::client::legacy::Client::builder(TokioExecutor::new()).build(https));

    let client = Client::new(service, config.default_namespace);

    let pods: Api<Pod> = Api::default_namespaced(client);
    for p in pods.list(&Default::default()).await? {
        info!("{}", p.name_any());
    }

    Ok(())
}

//! In this example we will implement something similar to `kubectl get all`.

use kube::{
    Client,
    api::{Api, DynamicObject, ResourceExt},
    discovery::{Discovery, verbs},
};
use tracing::*;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    // Uses Aggregated Discovery API for fewer API calls (2 instead of N+2)
    let discovery = Discovery::new(client.clone()).run_aggregated().await?;
    for group in discovery.groups() {
        for (ar, caps) in group.recommended_resources() {
            if !caps.supports_operation(verbs::LIST) {
                continue;
            }
            let api: Api<DynamicObject> = Api::dynamic(client.clone(), &ar, &caps.scope).constrain_default();

            info!("{}/{} : {}", group.name(), ar.version, ar.kind);

            let list = api.list(&Default::default()).await?;
            for item in list.items {
                let name = item.name_any();
                let ns = item.metadata.namespace.map(|s| s + "/").unwrap_or_default();
                info!("\t\t{}{}", ns, name);
            }
        }
    }

    Ok(())
}

//! An example of how to list pods and select a field using a JSONPath expression.

use jsonpath_rust::JsonPath;
use k8s_openapi::api::core::v1::Pod;
use kube::{
    Client,
    api::{Api, ListParams},
};
use tracing::*;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    // Equivalent to `kubectl get pods --all-namespace \
    // -o jsonpath='{.items[*].spec.containers[*].image}'`
    let field_selector = std::env::var("FIELD_SELECTOR").unwrap_or_default();
    let jsonpath = {
        let path = std::env::var("JSONPATH").unwrap_or_else(|_| ".items[*].spec.containers[*].image".into());
        format!("${path}")
    };

    let pods: Api<Pod> = Api::<Pod>::all(client);
    let list_params = ListParams::default().fields(&field_selector);
    let list = pods.list(&list_params).await?;

    // Use the given JSONPATH to filter the ObjectList
    let list_json = serde_json::to_value(&list)?;
    for res in list_json.query(&jsonpath)? {
        info!("\t\t {}", res.as_str().unwrap());
    }
    Ok(())
}

//! An example of how to use a custom type for [`Api`] via type-erasure.

use kube::{
    Client,
    api::{Api, ApiResource, NotUsed, Object, ResourceExt},
};
use serde::Deserialize;
use tracing::*;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    // Here we replace heavy type k8s_openapi::api::core::v1::PodSpec with
    #[derive(Clone, Deserialize, Debug)]
    struct PodSpecSimple {
        containers: Vec<ContainerSimple>,
    }
    #[derive(Clone, Deserialize, Debug)]
    struct ContainerSimple {
        #[allow(dead_code)]
        image: String,
    }
    type PodSimple = Object<PodSpecSimple, NotUsed>;

    // Here we simply steal the type info from k8s_openapi, but we could create this from scratch.
    let ar = ApiResource::erase::<k8s_openapi::api::core::v1::Pod>(&());

    let pods: Api<PodSimple> = Api::default_namespaced_with(client, &ar);
    for p in pods.list(&Default::default()).await? {
        info!("Pod {} runs: {:?}", p.name_any(), p.spec.containers);
    }

    Ok(())
}

//! Watch any dynamically (via GVK) specified resources.

use futures::{StreamExt, TryStreamExt};
use kube::{
    api::{Api, DynamicObject, GroupVersionKind, ResourceExt},
    runtime::{WatchStreamExt, watcher},
};
use tracing::*;

use std::env;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = kube::Client::try_default().await?;

    // Take dynamic resource identifiers:
    let group = env::var("GROUP").unwrap_or_else(|_| "".into());
    let version = env::var("VERSION").unwrap_or_else(|_| "v1".into());
    let kind = env::var("KIND").unwrap_or_else(|_| "Pod".into());

    // Turn them into a GVK
    let gvk = GroupVersionKind::gvk(&group, &version, &kind);
    // Use API discovery to identify more information about the type (like its plural)
    let (ar, _caps) = kube::discovery::pinned_kind(&client, &gvk).await?;

    // Use the full resource info to create an Api with the ApiResource as its DynamicType
    let api = Api::<DynamicObject>::all_with(client, &ar);

    // For metadata-only watching, use Api::<PartialObjectMeta<DynamicObject>> instead.
    // PartialObjectMeta-based Api automatically uses efficient metadata-only requests.
    let mut items = watcher(api, watcher::Config::default()).applied_objects().boxed();
    while let Some(p) = items.try_next().await? {
        if let Some(ns) = p.namespace() {
            info!("saw {kind} {} in {ns}", p.name_any());
        } else {
            info!("saw {kind} {}", p.name_any());
        }
        trace!("full obj: {p:?}");
    }
    Ok(())
}

//! An example of watching custom ConfigMaps and abort when an error is encountered.

// demo structs: fields define the parse target, not all are read
#![allow(dead_code)]

use futures::prelude::*;
use k8s_openapi::api::core::v1::ConfigMap;
use kube::{
    Client, Resource,
    api::{Api, ObjectMeta},
    core::DeserializeGuard,
    runtime::{WatchStreamExt, reflector::ObjectRef, watcher},
};
use serde::Deserialize;
use tracing::*;

// Variant of ConfigMap that only accepts ConfigMaps with a CA certificate
// to demonstrate parsing failure
#[derive(Resource, Deserialize, Debug, Clone)]
#[resource(inherit = ConfigMap)]
struct CaConfigMap {
    metadata: ObjectMeta,
    data: CaConfigMapData,
}

#[derive(Deserialize, Debug, Clone)]
struct CaConfigMapData {
    #[serde(rename = "ca.crt")]
    ca_crt: String,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;
    let api = Api::<DeserializeGuard<CaConfigMap>>::default_namespaced(client);
    let use_watchlist = std::env::var("WATCHLIST").map(|s| s == "1").unwrap_or(false);
    let wc = if use_watchlist {
        // requires WatchList feature gate on 1.27 or later
        watcher::Config::default().streaming_lists()
    } else {
        watcher::Config::default()
    };

    watcher(api, wc)
        .applied_objects()
        .default_backoff()
        .try_for_each(|cm| async move {
            info!("saw {}", ObjectRef::from_obj(&cm));
            match cm.0 {
                Ok(cm) => info!("contents: {cm:?}"),
                Err(err) => warn!("failed to parse: {err}"),
            }
            Ok(())
        })
        .await?;
    Ok(())
}

//! An example of how to implement a limited variant of `kubectl events` to watch events in the
//! current context's namespace.

use std::pin::pin;

use futures::StreamExt;
use k8s_openapi::{
    api::{core::v1::ObjectReference, events::v1::Event},
    apimachinery::pkg::apis::meta::v1::Time,
    jiff,
    jiff::{SpanRound, Timestamp, Unit},
};
use kube::{
    Api, Client, ResourceExt,
    runtime::{WatchStreamExt, watcher},
};

/// limited variant of `kubectl events` that works on current context's namespace
///
/// requires a new enough cluster that apis/events.k8s.io/v1 work (kubectl uses corev1::Event)
/// for old style usage of core::v1::Event see node_watcher
#[derive(clap::Parser)]
struct App {
    /// Filter by object and kind
    ///
    /// Using --for=Pod/blog-xxxxx
    /// Note that kind name is case sensitive
    #[arg(long)]
    r#for: Option<String>,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;
    let app: App = clap::Parser::parse();

    let events: Api<Event> = Api::default_namespaced(client);
    let mut conf = watcher::Config::default();
    if let Some(forval) = app.r#for {
        if let Some((kind, name)) = forval.split_once('/') {
            conf = conf.fields(&format!("regarding.kind={kind},regarding.name={name}"));
        } else {
            return Err(anyhow::Error::msg("Usage: --for=<KIND>/<NAME>"));
        }
    }
    let event_stream = watcher(events, conf).default_backoff().applied_objects();
    let mut event_stream = pin!(event_stream);

    fn print_event(age: &str, reason: &str, obj: &str, note: &str) {
        println!("{age:<6} {reason:<15} {obj:<55} {note}");
    }
    print_event("AGE", "REASON", "OBJECT", "MESSAGE");
    while let Some(ev) = event_stream.next().await {
        match ev {
            Ok(ev) => {
                let age = ev
                    .creation_timestamp()
                    .map(format_creation)
                    .transpose()?
                    .unwrap_or_default();
                let reason = ev.reason.unwrap_or_default();
                let obj = ev.regarding.and_then(format_objref).unwrap_or_default();
                let note = ev.note.unwrap_or_default();
                print_event(&age, &reason, &obj, &note);
            }
            Err(err) => eprintln!("{:?}", anyhow::Error::new(err)),
        }
    }
    Ok(())
}

fn format_objref(oref: ObjectReference) -> Option<String> {
    Some(format!("{}/{}", oref.kind?, oref.name?))
}

fn format_creation(time: Time) -> Result<String, jiff::Error> {
    let dur = Timestamp::now().since(time.0)?.round(
        SpanRound::new()
            .largest(Unit::Day)
            .days_are_24_hours()
            .smallest(Unit::Minute),
    )?;
    Ok(match (dur.get_days(), dur.get_hours(), dur.get_minutes()) {
        (days, _, _) if days > 0 => format!("{days}d"),
        (_, hours, _) if hours > 0 => format!("{hours}h"),
        (_, _, mins) => format!("{mins}m"),
    })
}

//! An example of how create a Job and wait for its completion.

use k8s_openapi::api::batch::v1::Job;
use kube::{
    Client,
    api::{Api, DeleteParams, PostParams},
    runtime::wait::{await_condition, conditions},
};
use tracing::info;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;
    let jobs: Api<Job> = Api::default_namespaced(client);

    info!("Creating job");
    let name = "empty-job";
    let data = serde_json::from_value(serde_json::json!({
        "apiVersion": "batch/v1",
        "kind": "Job",
        "metadata": {
            "name": name,
        },
        "spec": {
            "template": {
                "metadata": {
                    "name": "empty-job-pod"
                },
                "spec": {
                    "containers": [{
                        "name": "empty",
                        "image": "alpine:latest"
                    }],
                    "restartPolicy": "Never",
                }
            }
        }
    }))?;
    jobs.create(&PostParams::default(), &data).await?;

    info!("Waiting for job to complete");
    let cond = await_condition(jobs.clone(), name, conditions::is_job_completed());
    let _ = tokio::time::timeout(std::time::Duration::from_secs(20), cond).await?;

    info!("Cleaning up job record");
    jobs.delete(name, &DeleteParams::background()).await?;
    Ok(())
}

//! This is a simple imitation of the basic functionality of kubectl:
//! kubectl {get, delete, apply, watch, edit} <resource> [name]
//! with labels and namespace selectors supported.
use anyhow::{Context, Result, bail};
use futures::{StreamExt, TryStreamExt};
use k8s_openapi::{
    apimachinery::pkg::apis::meta::v1::Time,
    jiff,
    jiff::{SpanRound, Timestamp, Unit},
};
use kube::{
    Client,
    api::{Api, DynamicObject, ListParams, Patch, PatchParams, ResourceExt},
    core::GroupVersionKind,
    discovery::{ApiCapabilities, ApiResource, Discovery},
    runtime::{
        WatchStreamExt,
        wait::{await_condition, conditions::is_deleted},
        watcher,
    },
};
use tracing::*;

#[derive(clap::Parser)]
struct App {
    #[arg(long, short, default_value_t = OutputMode::Pretty)]
    output: OutputMode,
    #[arg(long, short)]
    file: Option<std::path::PathBuf>,
    #[arg(long, short = 'l')]
    selector: Option<String>,
    #[arg(long, short)]
    namespace: Option<String>,
    #[arg(long, short = 'A')]
    all: bool,
    verb: Verb,
    resource: Option<String>,
    name: Option<String>,
}

#[derive(Clone, PartialEq, Eq, clap::ValueEnum)]
enum OutputMode {
    Pretty,
    Yaml,
}

impl OutputMode {
    fn as_str(&self) -> &'static str {
        match self {
            Self::Pretty => "pretty",
            Self::Yaml => "yaml",
        }
    }
}

impl std::fmt::Display for OutputMode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.pad(self.as_str())
    }
}

#[derive(Clone, PartialEq, Eq, Debug, clap::ValueEnum)]
enum Verb {
    Get,
    Delete,
    Edit,
    Watch,
    Apply,
}

fn resolve_api_resource(discovery: &Discovery, name: &str) -> Option<(ApiResource, ApiCapabilities)> {
    // iterate through groups to find matching kind/plural names at recommended versions
    // and then take the minimal match by group.name (equivalent to sorting groups by group.name).
    // this is equivalent to kubectl's api group preference
    discovery
        .groups()
        .flat_map(|group| {
            group
                .resources_by_stability()
                .into_iter()
                .map(move |res| (group, res))
        })
        .filter(|(_, (res, _))| {
            // match on both resource name and kind name
            // ideally we should allow shortname matches as well
            name.eq_ignore_ascii_case(&res.kind) || name.eq_ignore_ascii_case(&res.plural)
        })
        .min_by_key(|(group, _res)| group.name())
        .map(|(_, res)| res)
}

impl App {
    async fn get(&self, api: Api<DynamicObject>, lp: ListParams) -> Result<()> {
        let mut result: Vec<_> = if let Some(n) = &self.name {
            vec![api.get(n).await?]
        } else {
            api.list(&lp).await?.items
        };
        result.iter_mut().for_each(|x| x.managed_fields_mut().clear()); // hide managed fields

        match self.output {
            OutputMode::Yaml => println!("{}", serde_saphyr::to_string(&result)?),
            OutputMode::Pretty => {
                // Display style; size columns according to longest name
                let max_name = result.iter().map(|x| x.name_any().len() + 2).max().unwrap_or(63);
                println!("{0:<width$} {1:<20}", "NAME", "AGE", width = max_name);
                for inst in result {
                    let age = inst
                        .creation_timestamp()
                        .map(format_creation)
                        .transpose()?
                        .unwrap_or_default();
                    println!("{0:<width$} {1:<20}", inst.name_any(), age, width = max_name);
                }
            }
        }
        Ok(())
    }

    async fn delete(&self, api: Api<DynamicObject>, lp: ListParams) -> Result<()> {
        if let Some(n) = &self.name {
            if let either::Either::Left(pdel) = api.delete(n, &Default::default()).await? {
                // await delete before returning
                await_condition(api, n, is_deleted(&pdel.uid().unwrap())).await?;
            }
        } else {
            api.delete_collection(&Default::default(), &lp).await?;
        }
        Ok(())
    }

    async fn watch(&self, api: Api<DynamicObject>, mut wc: watcher::Config) -> Result<()> {
        if let Some(n) = &self.name {
            wc = wc.fields(&format!("metadata.name={n}"));
        }
        // present a dumb table for it for now. kubectl does not do this anymore.
        let mut stream = watcher(api, wc).applied_objects().boxed();
        println!("{0:<width$} {1:<20}", "NAME", "AGE", width = 63);
        while let Some(inst) = stream.try_next().await? {
            let age = inst
                .creation_timestamp()
                .map(format_creation)
                .transpose()?
                .unwrap_or_default();
            println!("{0:<width$} {1:<20}", inst.name_any(), age, width = 63);
        }
        Ok(())
    }

    async fn edit(&self, api: Api<DynamicObject>) -> Result<()> {
        if let Some(n) = &self.name {
            let mut orig = api.get(n).await?;
            orig.managed_fields_mut().clear(); // hide managed fields
            let input = serde_saphyr::to_string(&orig)?;
            debug!("opening {} in {:?}", orig.name_any(), edit::get_editor());
            let edited = edit::edit(&input)?;
            if edited != input {
                info!("updating changed object {}", orig.name_any());
                let data: DynamicObject = serde_saphyr::from_str(&edited)?;
                // NB: simplified kubectl constructs a merge-patch of differences
                api.replace(n, &Default::default(), &data).await?;
            }
        } else {
            warn!("need a name to edit");
        }
        Ok(())
    }

    async fn apply(&self, client: Client, discovery: &Discovery) -> Result<()> {
        let ssapply = PatchParams::apply("kubectl-light").force();
        let pth = self.file.clone().expect("apply needs a -f file supplied");
        let yaml = std::fs::read(&pth).with_context(|| format!("Failed to read {}", pth.display()))?;
        let docs: Vec<DynamicObject> = serde_saphyr::from_slice_multiple(&yaml)?;

        for obj in docs {
            let namespace = obj.metadata.namespace.as_deref().or(self.namespace.as_deref());
            let gvk = if let Some(tm) = &obj.types {
                GroupVersionKind::try_from(tm)?
            } else {
                bail!("cannot apply object without valid TypeMeta {:?}", obj);
            };
            let name = obj.name_any();
            if let Some((ar, caps)) = discovery.resolve_gvk(&gvk) {
                let api = dynamic_api(ar, caps, client.clone(), namespace, false);
                trace!("Applying {}: \n{}", gvk.kind, serde_saphyr::to_string(&obj)?);
                let data: serde_json::Value = serde_json::to_value(&obj)?;
                let _r = api.patch(&name, &ssapply, &Patch::Apply(data)).await?;
                info!("applied {} {}", gvk.kind, name);
            } else {
                warn!("Cannot apply document for unknown {:?}", gvk);
            }
        }
        Ok(())
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt::init();
    let app: App = clap::Parser::parse();

    let kubeconfig = kube::config::Kubeconfig::read()?;
    let client = Client::try_from(kubeconfig)?;

    // discovery (to be able to infer apis from kind/plural only)
    let discovery = Discovery::new(client.clone()).run_aggregated().await?;

    // Defer to methods for verbs
    if let Some(resource) = &app.resource {
        // Common discovery, parameters, and api configuration for a single resource
        let (ar, caps) = resolve_api_resource(&discovery, resource)
            .with_context(|| format!("resource {resource:?} not found in cluster"))?;
        let mut lp = ListParams::default();
        if let Some(label) = &app.selector {
            lp = lp.labels(label);
        }

        let mut wc = watcher::Config::default();
        if let Some(label) = &app.selector {
            wc = wc.labels(label);
        }

        let api = dynamic_api(ar, caps, client, app.namespace.as_deref(), app.all);

        tracing::info!(?app.verb, ?resource, name = ?app.name.clone().unwrap_or_default(), "requested objects");
        match app.verb {
            Verb::Edit => app.edit(api).await?,
            Verb::Get => app.get(api, lp).await?,
            Verb::Delete => app.delete(api, lp).await?,
            Verb::Watch => app.watch(api, wc).await?,
            Verb::Apply => bail!("verb {:?} cannot act on an explicit resource", app.verb),
        }
    } else if app.verb == Verb::Apply {
        app.apply(client, &discovery).await? // multi-resource special behaviour
    }
    Ok(())
}

fn dynamic_api(
    ar: ApiResource,
    caps: ApiCapabilities,
    client: Client,
    ns: Option<&str>,
    all: bool,
) -> Api<DynamicObject> {
    let api = Api::dynamic(client, &ar, &caps.scope);
    match (all, ns) {
        (true, _) => api,
        (false, Some(ns)) => api.constrain(ns),
        (false, None) => api.constrain_default(),
    }
}

fn format_creation(time: Time) -> std::result::Result<String, jiff::Error> {
    let dur = Timestamp::now().since(time.0)?.round(
        SpanRound::new()
            .largest(Unit::Day)
            .days_are_24_hours()
            .smallest(Unit::Minute),
    )?;
    Ok(match (dur.get_days(), dur.get_hours(), dur.get_minutes()) {
        (days, _, _) if days > 0 => format!("{days}d"),
        (_, hours, _) if hours > 0 => format!("{hours}h"),
        (_, _, mins) => format!("{mins}m"),
    })
}

