//! An example of how to watch multiple resources at the same time.

use futures::{StreamExt, TryStreamExt, stream};
use k8s_openapi::api::{
    apps::v1::Deployment,
    core::v1::{ConfigMap, Secret},
};
use kube::{
    Client,
    api::{Api, ResourceExt},
    runtime::{WatchStreamExt, watcher},
};
use tracing::*;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    let deploys: Api<Deployment> = Api::default_namespaced(client.clone());
    let cms: Api<ConfigMap> = Api::default_namespaced(client.clone());
    let secret: Api<Secret> = Api::default_namespaced(client.clone());
    let dep_watcher = watcher(deploys, watcher::Config::default());
    let cm_watcher = watcher(cms, watcher::Config::default());
    let sec_watcher = watcher(secret, watcher::Config::default());

    // select on applied events from all watchers
    let mut combo_stream = stream::select_all(vec![
        dep_watcher.applied_objects().map_ok(Watched::Deploy).boxed(),
        cm_watcher.applied_objects().map_ok(Watched::Config).boxed(),
        sec_watcher.applied_objects().map_ok(Watched::Secret).boxed(),
    ]);
    // SelectAll Stream elements must have the same Item, so all packed in this:
    #[allow(clippy::large_enum_variant)]
    enum Watched {
        Config(ConfigMap),
        Deploy(Deployment),
        Secret(Secret),
    }
    while let Some(o) = combo_stream.try_next().await? {
        match o {
            Watched::Config(cm) => info!("Got configmap: {}", cm.name_any()),
            Watched::Deploy(d) => info!("Got deployment: {}", d.name_any()),
            Watched::Secret(s) => info!("Got secret: {}", s.name_any()),
        }
    }
    Ok(())
}

//! An example of how to keep an up-to-date reflector of Nodes in memory and continuously print out
//! the Node's information.

use std::pin::pin;

use futures::TryStreamExt;
use k8s_openapi::api::core::v1::Node;
use kube::{
    Client,
    api::{Api, ResourceExt},
    runtime::{Predicate, WatchStreamExt, predicates, reflector, watcher},
};
use tracing::*;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    let nodes: Api<Node> = Api::all(client.clone());
    let wc = watcher::Config::default()
        .labels("kubernetes.io/arch=amd64") // filter instances by label
        .timeout(10); // short watch timeout in this example

    let (reader, writer) = reflector::store();
    let stream = watcher(nodes, wc)
        .default_backoff()
        .reflect(writer)
        .applied_objects()
        .predicate_filter(
            predicates::labels.combine(predicates::annotations),
            Default::default(),
        );
    let mut stream = pin!(stream);

    // Periodically read our state in the background
    tokio::spawn(async move {
        reader.wait_until_ready().await.unwrap();
        loop {
            let nodes = reader.state().iter().map(|r| r.name_any()).collect::<Vec<_>>();
            info!("Current {} nodes: {:?}", nodes.len(), nodes);
            tokio::time::sleep(std::time::Duration::from_secs(10)).await;
        }
    });

    // Log applied events with changes from the reflector
    while let Some(node) = stream.try_next().await? {
        info!("saw node {} with new labels/annots", node.name_any());
    }

    Ok(())
}

//! An example of how to watch Nodes and check for any Node failures.

use std::pin::pin;

use futures::TryStreamExt;
use k8s_openapi::api::core::v1::{Event, Node};
use kube::{
    api::{Api, ListParams, ResourceExt},
    client::{Client, scope},
    runtime::{WatchStreamExt, watcher},
};
use tracing::*;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;
    let nodes: Api<Node> = Api::all(client.clone());

    let use_watchlist = std::env::var("WATCHLIST").map(|s| s == "1").unwrap_or(false);
    let wc = if use_watchlist {
        // requires WatchList feature gate on 1.27 or later
        watcher::Config::default().streaming_lists()
    } else {
        watcher::Config::default()
    };
    let obs = watcher(nodes, wc).default_backoff().applied_objects();
    let mut obs = pin!(obs);

    while let Some(n) = obs.try_next().await? {
        check_for_node_failures(&client, n).await?;
    }
    Ok(())
}

// A simple node problem detector
async fn check_for_node_failures(client: &Client, o: Node) -> anyhow::Result<()> {
    let name = o.name_any();
    // Nodes often modify a lot - only print broken nodes
    if let Some(true) = o.spec.unwrap().unschedulable {
        let failed = o
            .status
            .unwrap()
            .conditions
            .unwrap()
            .into_iter()
            .filter(|c| {
                // In a failed state either some of the extra conditions are not False
                // Or the Ready state is False
                (c.status == "True" && c.type_ != "Ready") || (c.status == "False" && c.type_ == "Ready")
            })
            .map(|c| c.message)
            .collect::<Vec<_>>(); // failed statuses
        warn!("Unschedulable Node: {}, ({:?})", name, failed);
        // Find events related to this node
        let opts =
            ListParams::default().fields(&format!("involvedObject.kind=Node,involvedObject.name={name}"));
        let evlist = client.list::<Event>(&opts, &scope::Cluster).await?;
        for e in evlist {
            warn!("Node event: {:?}", serde_json::to_string_pretty(&e)?);
        }
    } else {
        info!("Healthy node: {}", name);
    }
    Ok(())
}

//! An example of how to manipulate Pods, like creation, mutation and deletion.

use k8s_openapi::api::core::v1::Pod;
use serde_json::json;
use tracing::*;

use kube::{
    Client,
    api::{Api, DeleteParams, ListParams, Patch, PatchParams, PostParams, ResourceExt},
    runtime::wait::{await_condition, conditions::is_pod_running},
};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    // Manage pods
    let pods: Api<Pod> = Api::default_namespaced(client);

    // Create Pod blog
    info!("Creating Pod instance blog");
    let p: Pod = serde_json::from_value(json!({
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": { "name": "blog" },
        "spec": {
            "containers": [{
              "name": "blog",
              "image": "clux/blog:0.1.0"
            }],
        }
    }))?;

    let pp = PostParams::default();
    match pods.create(&pp, &p).await {
        Ok(o) => {
            let name = o.name_any();
            assert_eq!(p.name_any(), name);
            info!("Created {}", name);
        }
        Err(kube::Error::Api(ae)) => assert_eq!(ae.code, 409), // if you skipped delete, for instance
        Err(e) => return Err(e.into()),                        // any other case is probably bad
    }

    // Watch it phase for a few seconds
    let establish = await_condition(pods.clone(), "blog", is_pod_running());
    let _ = tokio::time::timeout(std::time::Duration::from_secs(15), establish).await?;

    // Verify we can get it
    info!("Get Pod blog");
    let p1cpy = pods.get("blog").await?;
    if let Some(spec) = &p1cpy.spec {
        info!("Got blog pod with containers: {:?}", spec.containers);
        assert_eq!(spec.containers[0].name, "blog");
    }

    // Replace its spec
    info!("Patch Pod blog");
    let patch = json!({
        "metadata": {
            "resourceVersion": p1cpy.resource_version(),
        },
        "spec": {
            "activeDeadlineSeconds": 5
        }
    });
    let patchparams = PatchParams::default();
    let p_patched = pods.patch("blog", &patchparams, &Patch::Merge(&patch)).await?;
    assert_eq!(p_patched.spec.unwrap().active_deadline_seconds, Some(5));

    let lp = ListParams::default().fields(&format!("metadata.name={}", "blog")); // only want results for our pod
    for p in pods.list(&lp).await? {
        info!("Found Pod: {}", p.name_any());
    }

    // Delete it
    let dp = DeleteParams::default();
    pods.delete("blog", &dp).await?.map_left(|pdel| {
        assert_eq!(pdel.name_any(), "blog");
        info!("Deleting blog pod started: {:?}", pdel);
    });

    Ok(())
}

//! An example of how to attach to a container inside a Pod and print separated or combined
//! stdout/stderr output.

use std::io::Write;

use futures::{StreamExt, TryStreamExt, join, stream};
use k8s_openapi::api::core::v1::Pod;
use tracing::*;

use kube::{
    Client,
    api::{
        Api, AttachParams, AttachedProcess, DeleteParams, PostParams, ResourceExt, WatchEvent, WatchParams,
    },
};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    info!("Creating a Pod that outputs numbers for 15s");
    let p: Pod = serde_json::from_value(serde_json::json!({
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": { "name": "example" },
        "spec": {
            "containers": [{
                "name": "example",
                "image": "alpine",
                "command": ["sh", "-c", "for i in `seq 15`; do if [ $i -lt 7 ]; then echo \"o $i\"; else echo \"e $i\" 1>&2; fi; sleep 1; done;"],
            }],
        }
    }))?;

    let pods: Api<Pod> = Api::default_namespaced(client);
    // Stop on error including a pod already exists or is still being deleted.
    pods.create(&PostParams::default(), &p).await?;

    // Wait until the pod is running, otherwise we get 500 error.
    let wp = WatchParams::default().fields("metadata.name=example").timeout(10);
    let mut stream = pods.watch(&wp, "0").await?.boxed();
    while let Some(status) = stream.try_next().await? {
        match status {
            WatchEvent::Added(o) => {
                info!("Added {}", o.name_any());
            }
            WatchEvent::Modified(o) => {
                let s = o.status.as_ref().expect("status exists on pod");
                if s.phase.clone().unwrap_or_default() == "Running" {
                    info!("Ready to attach to {}", o.name_any());
                    break;
                }
            }
            _ => {}
        }
    }

    let ap = AttachParams::default();
    // Attach to see numbers printed on stdout.
    let attached = pods.attach("example", &ap).await?;
    // Separate stdout/stderr outputs
    separate_outputs(attached).await;
    // Combining stdout and stderr output.
    // combined_output(proc).await;

    // Delete it
    pods.delete("example", &DeleteParams::default())
        .await?
        .map_left(|pdel| {
            assert_eq!(pdel.name_any(), "example");
        });

    Ok(())
}

#[allow(dead_code)]
async fn separate_outputs(mut attached: AttachedProcess) {
    let stdout = tokio_util::io::ReaderStream::new(attached.stdout().unwrap());
    let stdouts = stdout.for_each(|res| async {
        if let Ok(bytes) = res {
            let out = std::io::stdout();
            out.lock().write_all(&bytes).unwrap();
        }
    });
    let stderr = tokio_util::io::ReaderStream::new(attached.stderr().unwrap());
    let stderrs = stderr.for_each(|res| async {
        if let Ok(bytes) = res {
            let out = std::io::stderr();
            out.lock().write_all(&bytes).unwrap();
        }
    });

    join!(stdouts, stderrs);
    if let Some(status) = attached.take_status().unwrap().await {
        info!("{:?}", status);
    }
}

#[allow(dead_code)]
async fn combined_output(mut attached: AttachedProcess) {
    let stdout = tokio_util::io::ReaderStream::new(attached.stdout().unwrap());
    let stderr = tokio_util::io::ReaderStream::new(attached.stderr().unwrap());
    let outputs = stream::select(stdout, stderr).for_each(|res| async {
        if let Ok(bytes) = res {
            let out = std::io::stdout();
            out.lock().write_all(&bytes).unwrap();
        }
    });
    outputs.await;
    if let Some(status) = attached.take_status().unwrap().await {
        info!("{:?}", status);
    }
}

//! An example of how to implement a limited `kubectl cp`.

use futures::{StreamExt, TryStreamExt};
use k8s_openapi::api::core::v1::Pod;
use tracing::*;

use kube::{
    Client,
    api::{Api, AttachParams, DeleteParams, PostParams, ResourceExt, WatchEvent, WatchParams},
};
use tokio::io::AsyncWriteExt;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    let p: Pod = serde_json::from_value(serde_json::json!({
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": { "name": "example" },
        "spec": {
            "containers": [{
                "name": "example",
                "image": "alpine",
                // Do nothing
                "command": ["tail", "-f", "/dev/null"],
            }],
        }
    }))?;

    let pods: Api<Pod> = Api::default_namespaced(client);
    // Stop on error including a pod already exists or still being deleted.
    pods.create(&PostParams::default(), &p).await?;

    // Wait until the pod is running, otherwise we get 500 error.
    let wp = WatchParams::default().fields("metadata.name=example").timeout(10);
    let mut stream = pods.watch(&wp, "0").await?.boxed();
    while let Some(status) = stream.try_next().await? {
        match status {
            WatchEvent::Added(o) => {
                info!("Added {}", o.name_any());
            }
            WatchEvent::Modified(o) => {
                let s = o.status.as_ref().expect("status exists on pod");
                if s.phase.clone().unwrap_or_default() == "Running" {
                    info!("Ready to attach to {}", o.name_any());
                    break;
                }
            }
            _ => {}
        }
    }

    let data = "data for pod";
    let file_name = "foo.txt";

    // Write the data to pod
    {
        let mut header = tar::Header::new_gnu();
        header.set_path(file_name).unwrap();
        header.set_size(data.len() as u64);
        header.set_cksum();

        let mut ar = tar::Builder::new(Vec::new());
        ar.append(&header, &mut data.as_bytes()).unwrap();
        let data = ar.into_inner().unwrap();

        let ap = AttachParams::default().stdin(true).stderr(false);
        let mut tar = pods
            .exec("example", vec!["tar", "xf", "-", "-C", "/"], &ap)
            .await?;
        tar.stdin().unwrap().write_all(&data).await?;
    }

    // Check that the file was written
    {
        let ap = AttachParams::default().stderr(false);
        let mut cat = pods
            .exec("example", vec!["cat", &format!("/{file_name}")], &ap)
            .await?;
        let mut cat_out = tokio_util::io::ReaderStream::new(cat.stdout().unwrap());
        let next_stdout = cat_out.next().await.unwrap()?;

        info!("Contents of the file on the pod: {:?}", next_stdout);
        assert_eq!(next_stdout, data);
    }

    // Clean up the pod
    pods.delete("example", &DeleteParams::default())
        .await?
        .map_left(|pdel| {
            assert_eq!(pdel.name_any(), "example");
        });

    Ok(())
}

