//! An example of how to execute a command on a container of a Pod.

use futures::{StreamExt, TryStreamExt};
use k8s_openapi::api::core::v1::Pod;
use tracing::*;

use kube::{
    Client,
    api::{
        Api, AttachParams, AttachedProcess, DeleteParams, PostParams, ResourceExt, WatchEvent, WatchParams,
    },
};
use tokio::io::AsyncWriteExt;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;

    let p: Pod = serde_json::from_value(serde_json::json!({
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": { "name": "example" },
        "spec": {
            "containers": [{
                "name": "example",
                "image": "alpine",
                // Do nothing
                "command": ["tail", "-f", "/dev/null"],
            }],
        }
    }))?;

    let pods: Api<Pod> = Api::default_namespaced(client);
    // Stop on error including a pod already exists or is still being deleted.
    pods.create(&PostParams::default(), &p).await?;

    // Wait until the pod is running, otherwise we get 500 error.
    let wp = WatchParams::default().fields("metadata.name=example").timeout(10);
    let mut stream = pods.watch(&wp, "0").await?.boxed();
    while let Some(status) = stream.try_next().await? {
        match status {
            WatchEvent::Added(o) => {
                info!("Added {}", o.name_any());
            }
            WatchEvent::Modified(o) => {
                let s = o.status.as_ref().expect("status exists on pod");
                if s.phase.clone().unwrap_or_default() == "Running" {
                    info!("Ready to attach to {}", o.name_any());
                    break;
                }
            }
            _ => {}
        }
    }

    // These examples are mostly taken from Python client's integration tests.
    {
        let attached = pods
            .exec(
                "example",
                vec!["sh", "-c", "for i in $(seq 1 3); do date; done"],
                &AttachParams::default().stderr(false),
            )
            .await?;
        let output = get_output(attached).await;
        println!("{output}");
        assert_eq!(output.lines().count(), 3);
    }

    {
        let attached = pods
            .exec("example", vec!["uptime"], &AttachParams::default().stderr(false))
            .await?;
        let output = get_output(attached).await;
        println!("{output}");
        assert_eq!(output.lines().count(), 1);
    }

    // Stdin example
    {
        let mut attached = pods
            .exec(
                "example",
                vec!["sh"],
                &AttachParams::default().stdin(true).stderr(false),
            )
            .await?;
        let mut stdin_writer = attached.stdin().unwrap();
        let mut stdout_stream = tokio_util::io::ReaderStream::new(attached.stdout().unwrap());
        let next_stdout = stdout_stream.next();
        stdin_writer.write_all(b"echo test string 1\n").await?;
        let stdout = String::from_utf8(next_stdout.await.unwrap().unwrap().to_vec()).unwrap();
        println!("{stdout}");
        assert_eq!(stdout, "test string 1\n");

        // AttachedProcess provides access to a future that resolves with a status object.
        let status = attached.take_status().unwrap();
        // Send `exit 1` to get a failure status.
        stdin_writer.write_all(b"exit 1\n").await?;
        if let Some(status) = status.await {
            println!("{status:?}");
            assert_eq!(status.status, Some("Failure".to_owned()));
            assert_eq!(status.reason, Some("NonZeroExitCode".to_owned()));
        }
    }

    // Delete it
    pods.delete("example", &DeleteParams::default())
        .await?
        .map_left(|pdel| {
            assert_eq!(pdel.name_any(), "example");
        });

    Ok(())
}

async fn get_output(mut attached: AttachedProcess) -> String {
    let stdout = tokio_util::io::ReaderStream::new(attached.stdout().unwrap());
    let out = stdout
        .filter_map(|r| async { r.ok().and_then(|v| String::from_utf8(v.to_vec()).ok()) })
        .collect::<Vec<_>>()
        .await
        .join("");
    attached.join().await.unwrap();
    out
}

//! An example of how read debug logs directly for a Node via the kubelet,

use futures::TryStreamExt;
use k8s_openapi::api::core::v1::Pod;
use tracing::*;

use futures::AsyncBufReadExt;
use kube::{
    Client, Config,
    api::{Api, DeleteParams, ResourceExt},
    core::{kubelet_debug::KubeletDebugParams, subresource::LogParams},
};
use serde_json::json;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();

    let client = Client::try_default().await?;
    let pods: Api<Pod> = Api::namespaced(client, "default");

    // create busybox pod that's alive for at most 30s
    let p: Pod = serde_json::from_value(json!({
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": {
            "name": "example",
            "labels": { "app": "kube-rs-test" },
        },
        "spec": {
            "terminationGracePeriodSeconds": 1,
            "restartPolicy": "Never",
            "containers": [{
              "name": "busybox",
              "image": "busybox:stable",
              "command": ["sh", "-c", "for i in $(seq 1 5); do echo kube $i; sleep 0.1; done"],
            }],
        }
    }))?;

    match pods.create(&Default::default(), &p).await {
        Ok(o) => assert_eq!(p.name_unchecked(), o.name_unchecked()),
        Err(kube::Error::Api(ae)) => assert_eq!(ae.code, 409), // if we failed to clean-up
        Err(e) => return Err(e.into()),                        // any other case if a failure
    }

    // wait for container to finish
    tokio::time::sleep(std::time::Duration::from_secs(2)).await;

    // Grab logs directly via the kubelet_debug interface
    kubelet_log().await?;

    // Delete it
    info!("deleting");
    let _ = pods.delete("example", &DeleteParams::default()).await?;

    Ok(())
}

async fn kubelet_log() -> anyhow::Result<()> {
    // Create a client for node proxy
    // This uses an insecure configuration to talk to the kubelet directly
    // and assumes 10250 is a reachable kubelet port (k3d default)
    let mut config = Config::infer().await?;
    config.accept_invalid_certs = true;
    config.cluster_url = "https://localhost:10250".parse().unwrap();
    let client: Client = config.try_into()?;

    // Get logs directly from the node, bypassing the kube-apiserver
    let kp = KubeletDebugParams {
        name: "example",
        namespace: "default",
        ..Default::default()
    };
    let lp = LogParams::default();
    let mut logs_stream = client.kubelet_node_logs(&kp, "busybox", &lp).await?.lines();

    while let Some(line) = logs_stream.try_next().await? {
        println!("{line}");
    }
    Ok(())
}

//! This example shows how to do pagination with the raw `Api` only.
//!
//! In many realistic setups that need a continual, paginated, safe list-watch;
//! the `watcher` is an easier abstraction that has configurable pagination built in.

use k8s_openapi::api::core::v1::Pod;
use kube::{
    Client,
    api::{Api, ListParams, ResourceExt},
};
use tracing::*;

const PAGE_SIZE: u32 = 5;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let client = Client::try_default().await?;
    let api = Api::<Pod>::default_namespaced(client);

    let mut continue_token: Option<String> = None;
    for page in 1.. {
        info!("Fetching Page #{page}");
        continue_token = fetch_page(&api, continue_token).await?;

        if continue_token.is_none() {
            info!("End of list");
            break;
        }
    }

    Ok(())
}

async fn fetch_page(api: &Api<Pod>, continue_token: Option<String>) -> anyhow::Result<Option<String>> {
    let mut lp = ListParams::default().limit(PAGE_SIZE);
    if let Some(token) = continue_token {
        lp = lp.continue_token(&token);
    }

    let pods = api.list(&lp).await?;
    let continue_token = pods.metadata.continue_.clone();
    for p in pods {
        info!("Found Pod: {}", p.name_any());
    }

    Ok(continue_token)
}

//! An example of how to connect to port 80 of the example pod, send a request, and stream the
